@Test
public void testEmptySegmentPruner() {
    BrokerRequest brokerRequest1 = CalciteSqlCompiler.compileToBrokerRequest(QUERY_1);
    BrokerRequest brokerRequest2 = CalciteSqlCompiler.compileToBrokerRequest(QUERY_2);
    BrokerRequest brokerRequest3 = CalciteSqlCompiler.compileToBrokerRequest(QUERY_3);
    // NOTE: Ideal state and external view are not used in the current implementation
    IdealState idealState = Mockito.mock(IdealState.class);
    ExternalView externalView = Mockito.mock(ExternalView.class);
    TableConfig tableConfig = getTableConfig(RAW_TABLE_NAME, TableType.REALTIME);
    // init with list of segments
    EmptySegmentPruner segmentPruner = new EmptySegmentPruner(tableConfig, _propertyStore);
    Set<String> onlineSegments = new HashSet<>();
    String segment0 = "segment0";
    onlineSegments.add(segment0);
    setSegmentZKTotalDocsMetadata(REALTIME_TABLE_NAME, segment0, 10);
    String segment1 = "segment1";
    onlineSegments.add(segment1);
    setSegmentZKTotalDocsMetadata(REALTIME_TABLE_NAME, segment1, 0);
    segmentPruner.init(idealState, externalView, onlineSegments);
    assertEquals(segmentPruner.prune(brokerRequest1, new HashSet<>(Arrays.asList(segment0, segment1))), new HashSet<>(Collections.singletonList(segment0)));
    assertEquals(segmentPruner.prune(brokerRequest2, new HashSet<>(Arrays.asList(segment0, segment1))), new HashSet<>(Collections.singletonList(segment0)));
    assertEquals(segmentPruner.prune(brokerRequest3, new HashSet<>(Arrays.asList(segment0, segment1))), new HashSet<>(Collections.singletonList(segment0)));
    // init with empty list of segments
    segmentPruner = new EmptySegmentPruner(tableConfig, _propertyStore);
    onlineSegments.clear();
    segmentPruner.init(idealState, externalView, onlineSegments);
    assertEquals(segmentPruner.prune(brokerRequest1, Collections.emptySet()), Collections.emptySet());
    assertEquals(segmentPruner.prune(brokerRequest2, Collections.emptySet()), Collections.emptySet());
    assertEquals(segmentPruner.prune(brokerRequest3, Collections.emptySet()), Collections.emptySet());
    // Segments without metadata (not updated yet) should not be pruned
    String newSegment = "newSegment";
    onlineSegments.add(newSegment);
    segmentPruner.onAssignmentChange(idealState, externalView, onlineSegments);
    assertEquals(segmentPruner.prune(brokerRequest1, Collections.singleton(newSegment)), Collections.singleton(newSegment));
    assertEquals(segmentPruner.prune(brokerRequest2, Collections.singleton(newSegment)), Collections.singleton(newSegment));
    assertEquals(segmentPruner.prune(brokerRequest3, Collections.singleton(newSegment)), Collections.singleton(newSegment));
    // Segments without totalDocs metadata should not be pruned
    onlineSegments.clear();
    String segmentWithoutTotalDocsMetadata = "segmentWithoutTotalDocsMetadata";
    onlineSegments.add(segmentWithoutTotalDocsMetadata);
    SegmentZKMetadata segmentZKMetadataWithoutTotalDocsMetadata = new SegmentZKMetadata(segmentWithoutTotalDocsMetadata);
    segmentZKMetadataWithoutTotalDocsMetadata.setStatus(CommonConstants.Segment.Realtime.Status.IN_PROGRESS);
    ZKMetadataProvider.setSegmentZKMetadata(_propertyStore, REALTIME_TABLE_NAME, segmentZKMetadataWithoutTotalDocsMetadata);
    segmentPruner.onAssignmentChange(idealState, externalView, onlineSegments);
    assertEquals(segmentPruner.prune(brokerRequest1, Collections.singleton(segmentWithoutTotalDocsMetadata)), Collections.singleton(segmentWithoutTotalDocsMetadata));
    assertEquals(segmentPruner.prune(brokerRequest2, Collections.singleton(segmentWithoutTotalDocsMetadata)), Collections.singleton(segmentWithoutTotalDocsMetadata));
    assertEquals(segmentPruner.prune(brokerRequest3, Collections.singleton(segmentWithoutTotalDocsMetadata)), Collections.singleton(segmentWithoutTotalDocsMetadata));
