@Test
public void testPersistTaskMetadata() {
    DummyTaskMetadata taskMetadata = new DummyTaskMetadata("TestTable_OFFLINE", 1000);
    HelixPropertyStore<ZNRecord> mockPropertyStore = Mockito.mock(HelixPropertyStore.class);
    String expectedPath = "/MINION_TASK_METADATA/TestTaskType/TestTable_OFFLINE";
    int expectedVersion = -1;
    // Test happy path. No exceptions thrown.
    when(mockPropertyStore.set(expectedPath, taskMetadata.toZNRecord(), expectedVersion, AccessOption.PERSISTENT)).thenReturn(true);
    MinionTaskMetadataUtils.persistTaskMetadata(mockPropertyStore, "TestTaskType", taskMetadata, expectedVersion);
    verify(mockPropertyStore, times(1)).set(expectedPath, taskMetadata.toZNRecord(), expectedVersion, AccessOption.PERSISTENT);
    // Test exception thrown
    when(mockPropertyStore.set(expectedPath, taskMetadata.toZNRecord(), -1, AccessOption.PERSISTENT)).thenReturn(false);
    try {
        MinionTaskMetadataUtils.persistTaskMetadata(mockPropertyStore, "TestTaskType", taskMetadata, expectedVersion);
        fail("ZkException should have been thrown");
    } catch (ZkException e) {
        verify(mockPropertyStore, times(2)).set(expectedPath, taskMetadata.toZNRecord(), expectedVersion, AccessOption.PERSISTENT);
        assertEquals(e.getMessage(), "Failed to persist minion metadata for task: TestTaskType and metadata:" + " {\"tableNameWithType\":\"TestTable_OFFLINE\"}");
    }
}

