    new RealtimeToOfflineSegmentsTaskMetadata(REALTIME_TABLE_NAME, 1590019200000L).toZNRecord());
    SegmentZKMetadata segmentZKMetadata = getSegmentZKMetadata("testTable__0__1__12345", Status.DONE, 1590220800000L, 1590307200000L, TimeUnit.MILLISECONDS, // 05-23-2020T08:00:00 UTC to 05-24-2020T08:00:00 UTC
    "download2");
    when(mockClusterInfoProvide.getSegmentsZKMetadata(REALTIME_TABLE_NAME)).thenReturn(Collections.singletonList(segmentZKMetadata));
    RealtimeToOfflineSegmentsTaskGenerator generator = new RealtimeToOfflineSegmentsTaskGenerator();
    generator.init(mockClusterInfoProvide);
    // Generated task should skip 2 days and have time window of [23 May 2020 UTC, 24 May 2020 UTC)
    List<PinotTaskConfig> pinotTaskConfigs = generator.generateTasks(Lists.newArrayList(realtimeTableConfig));
