    _serverMetrics = mock(ServerMetrics.class);
    _mutableSegment = MutableSegmentImplTestUtils.createMutableSegmentImpl(schema, Collections.emptySet(), Collections.emptySet(), new HashSet<>(Arrays.asList(INT_COL, STRING_COL)), Collections.singleton(JSON_COL), _serverMetrics);
