    int pos = 0;
    for (byte b : dataBytes) {
        writtenBuffer.putByte(pos++, b);
    }
    writtenBuffer.close();
    Mockito.when(_segmentMetadata.getAllColumns()).thenReturn(new HashSet<String>(Arrays.asList("foo")));
